parameters.jsCode:
const pkg = $json.output;
return pkg.shots
  .sort((a, b) => a.shot_number - b.shot_number)
  .map(s => ({ json: {
    shot_number: s.shot_number,
    duration_seconds: 5, // Kling pro clips are 5 s; keep compose timeline in sync
    image_prompt: s.image_prompt,
    end_image_prompt: s.end_image_prompt || s.image_prompt,
    video_prompt: s.video_prompt,
    video_title: pkg.video_title,
  }}));

const init = $('Voice · Init Upload (fal)').first().json;
const tts = $('Voice-over TTS (ElevenLabs)').first();
return [{ json: init, binary: { data: tts.binary.data } }];

parameters.jsonBody:
={{ (() => {
  const shots = $('Collect All Shots').first().json.shots;
  let t = 0;
  const video = shots.map(s => { const k = { url: s.video_url, timestamp: t, duration: s.duration_seconds }; t += s.duration_seconds; return k; });
  const voice_url = $('Voice · Init Upload (fal)').first().json.file_url;
  return { tracks: [
    { id: 'video', type: 'video', keyframes: video },
    { id: 'voice', type: 'audio', keyframes: [{ url: voice_url, timestamp: 0, duration: t }] }
  ] };
})() }}
